entries[434143] = { ["name"] = "Infliction of Sorrow", ["text"] = "Blood\nWhen Vampiric Strike damages an enemy affected by your Blood Plague, it extends the duration of the disease by 3 sec, and deals 20% of the remaining damage to the enemy.\n\nAfter Gift of the San'layn ends, the cooldown of your Death and Decay , and your next Heart Strike consumes the disease to deal 130% of their remaining damage to the target.\n\nUnholy\nWhen Vampiric Strike damages an enemy affected by your Virulent Plague, it extends the duration of the disease by 3 sec, and deals 10% of the remaining damage to the enemy.\n\nAfter Gift of the San'layn ends, the cooldown of your Death and Decay , and your next consumes the disease to deal 100% of their remaining damage to the target." }
entries[434144] = { ["name"] = "Infliction of Sorrow", ["text"] = "100 yd range\nInstant\nBlood\nWhen Vampiric Strike damages an enemy affected by your Blood Plague, it extends the duration of the disease by 3 sec, and deals 10% of the remaining damage to the enemy.\n\nAfter Gift of the San'layn ends, the cooldown of your Death and Decay , and your next Heart Strike consumes the disease to deal 100% of their remaining damage to the target.\n\nUnholy\nWhen Vampiric Strike damages an enemy affected by your Virulent Plague, it extends the duration of the disease by 3 sec, and deals 10% of the remaining damage to the enemy.\n\nAfter Gift of the San'layn ends, the cooldown of your Death and Decay , and your next consumes the disease to deal 100% of their remaining damage to the target." }
