entries[434152] = { ["name"] = "Gift of the San'layn", ["text"] = "Blood\nWhile Dancing Rune Weapon is active you gain Gift of the San'layn.\n\nGift of the San'layn increases the effectiveness of your Essence of the Blood Queen by 200%, and Vampiric Strike replaces your Heart Strike for the duration.\n\nUnholy\nWhile Dark Transformation is active you gain Gift of the San'layn.\n\nGift of the San'layn increases the effectiveness of your Essence of the Blood Queen by 100%, and Vampiric Strike replaces your for the duration." }
