entries[434251] = { ["name"] = "Fury of Urctos", ["text"] = "Instant\nSwipe at a the nearest enemy for 206 Physical damage and gain 1 stack of Rising Rage whenever you or an ally takes damage, granting 1 Primary Stat and stacking up to 30 times. This effect may occur every 3 sec.\n\nAt 30 stacks of Rising Rage , gain Fury of Urctos for 8 sec before consuming them, counterattacking all blows and regenerating 322 health every 1 sec.\n\nValid only for tank specializations.\n(100ms cooldown)" }
