entries[435103] = { ["name"] = "Dashing Windsteed", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Windsteeds are incredibly gentle and easy to train... if you can catch one.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435105] = { ["name"] = "Tracking Quest" }
entries[435107] = { ["name"] = "Forest Windsteed", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The fur of this Windsteed is not only colored to match its woodland home, but also usually contains bits of bark and leaves.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435108] = { ["name"] = "Daystorm Windsteed", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"It is said that when lightning strikes the sun, a gleaming beast in red armor would emerge from the heavens. The Daystorm Windsteed has never heard of these legends and has been here the entire time.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435109] = { ["name"] = "Feathered Windsurfer", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Check the current windspeed and elevation before mounting. Avoid trees and other tall objects. Damaged kites are ineligible for return or refund.\" - Windsurfer's Instruction Manual\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435110] = { ["name"] = "Extracting" }
entries[435114] = { ["name"] = "No Owner" }
entries[435115] = { ["name"] = "Guardian Quilen", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"When Quan the Relentless fell in battle, his loyal hounds waited for his return. Millenia later, they remain patient.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435118] = { ["name"] = "Marble Quilen", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Created by a mogu sorcerer who breathed life into their favorite pet rock.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435119] = { ["name"] = "Web Spin", ["text"] = "300 yd range\nInstant\nUlgrax spews webs at a player and all allies within 10 yards, inflicting 17331401 Nature damage split evenly between all players, binding them to Ulgrax.\n\nBound players suffer 575632 Nature damage every 2 sec and are pulled toward Ulgrax. The strength with which Ulgrax pulls players is reduced for each bound player." }
entries[435123] = { ["name"] = "Gilded Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"It is said that an emperor once paid a large sum for a golden crane. Upon discovering that the crane was only colored like that of the precious metal, he hid with shame in his bedchambers for a week.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435124] = { ["name"] = "Luxurious Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"A majestic bird, but a rather picky eater.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435125] = { ["name"] = "Tropical Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This Jade Forest native uses its coloration as camouflage.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435126] = { ["name"] = "Silver Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This tall bird is one of the most graceful and elegant cranes, slightly moreso than the Bronze Crane but less than the Golden Crane.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435127] = { ["name"] = "Rose Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This brightly-colored bird is often confused with a flamingo or marabou.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435128] = { ["name"] = "Pale Riding Crane", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"I looked, and behold, a pale... crane?\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435129] = { ["name"] = "Chef's Seasoning", ["text"] = "100 yd range\nInstant\nThe chef seasons all players with salt, inflicting 4 Physical damage every 1.5 sec and increasing all damage taken by 10% for 9 sec.\n\nThis effect stacks." }
entries[435130] = { ["name"] = "Chef's Seasoning", ["text"] = "100 yd range\nInstant\nThe chef seasons all players with salt, inflicting 4 Physical damage every 1.5 sec and increasing all damage taken by 10% for 9 sec.\n\nThis effect stacks." }
entries[435131] = { ["name"] = "Snowy Riding Goat", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The Kun-Lai Summit mountain goats are known for climbing even the highest peaks in search of kafa beans and salt licks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435132] = { ["name"] = "Eat Me!" }
entries[435133] = { ["name"] = "Little Red Riding Goat", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"What this goat lacks in size, it makes up for in stubbornness.\"\nWorld Event:\nMists of Pandaria: Remix" }
entries[435134] = { ["name"] = "Eat Me!" }
entries[435135] = { ["name"] = "Delicious" }
entries[435136] = { ["name"] = "Venomous Lash", ["text"] = "20 yd range\n2 sec cast\nUlgrax flings poison at all players, inflicting 1726895 Nature damage on impact and an additional 978574 Nature damage every 1 sec for 6 sec." }
entries[435138] = { ["name"] = "Digestive Acid", ["text"] = "300 yd range\n2 sec cast\nUlgrax belches Digestive Acid at several players, inflicting 1726895 Nature damage every 2 sec for 6 sec.\n\nOnce removed venom erupts the victim's skin, inflicting 1151263 Nature damage to players within 7 yards and dissolving any webbing left behind by Stalker's Webbing ." }
entries[435140] = { ["name"] = "Into the Machine - Abandon" }
entries[435141] = { ["name"] = "Pact of the Deathbringer", ["text"] = "When you suffer a damaging effect equal to 2% of your maximum health, you instantly cast Death Pact at 25% effectiveness. Can only occur every 50 min.\n\nWhen a Reaper's Mark explodes, the cooldowns of this effect and Dark Pact are reduced by 25 sec." }
entries[435142] = { ["name"] = "Into the Machine - Abandon - Teleport" }
entries[435143] = { ["name"] = "Phase Blades", ["text"] = "Unlimited range\nChanneled (1.5 sec cast)\nSikran marks players and lunges towards each marked target inflicting 3741605 Physical damage to anyone in his path.\n\nAdditionally, players hit have their healing received reduced by 50% and an additional 474896 Shadow damage inflicted every 2 sec for 20 sec.\n\nMarked targets leave behind a Cosmic Simulacrum when struck." }
